    let v1 = a.add(&b).get()
    if v1 < 6.9 || v1 > 7.1 { print("FAIL_CHAIN_GET\n"); return 2 }

    // Method result as receiver (struct return), then get
    let v2 = a.add(&b).add(&c).get()
